fn increment[T](value: T) -> Int
  where T: Into[Int];
{
  return value.into() + 1;
}

fn main() -> Int {
  // Three separate monomorphised versions generated:
  let r1 = increment(41);   // increment_Int
  let r2 = increment(1.0);  // increment_Float64
  // All three calls have zero runtime overhead
  return r1;
}
